code='''from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    seen=set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                rr,cc=q.popleft(); comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            fill=2 if len(comp)%2==0 else 7
            for rr,cc in comp: out[rr][cc]=fill
    return out
'''
